#!/usr/bin/env python3
"""Check that a paper's printed text types no number by hand, and that every generated file is stamped.

Every number a reader sees must come from a macro that an experiment wrote (generated/*.tex), unless its line says
it is typed on purpose, with a reason: `%% typed: citing Smith et al. (2020)`. Names that contain digits (J2000, DE440)
go in an allow file: one regular expression per line, `#` starting a comment. The checker reads digits only; numbers
spelled out in words are the author's to replace with word macros.

What it reads: the main file and the files it \\input{}s, from \\begin{document} on, without comments. It skips the
generated files themselves, the files named with --skip, cite/ref/label/url/graphics arguments, \\newcommand
definitions and environment options. In prose, every digit is a finding. In mathematics, only a decimal number
(4.2) or an integer of two or more digits (300) is; a single digit (an index, an exponent, a 1/2) is structure.

Usage: check_numbers.py MAIN.tex [--allow numbers.allow] [--generated generated] [--skip authors ai_usage]
Exits 1 and lists file:line findings when a typed number is found or a generated file lacks its stamp.
"""
import argparse
import pathlib
import re
import sys

STAMP = "%% Generated by"
# Commands whose arguments never hold a reader's number: removed with their [optional] and {required} arguments.
DROP = ["cite", "citep", "citet", "citealt", "citealp", "citeauthor", "citeyear", "ref", "eqref", "label", "url",
        "href", "includegraphics", "input", "include", "bibliography", "bibliographystyle", "newcommand",
        "renewcommand", "providecommand", "def", "begin", "end", "email", "affiliation", "author", "graphicspath",
        "hspace", "vspace", "setlength", "uat"]
MATH_ENVS = ["equation", "equation*", "align", "align*", "gather", "gather*", "multline", "multline*", "eqnarray",
             "eqnarray*", "displaymath", "math"]


def strip_comments(text: str) -> tuple[str, set[int]]:
    """Remove comments, keeping line structure; return the text and the line numbers marked `%% typed:`."""
    out, typed = [], set()
    for i, line in enumerate(text.split("\n"), start=1):
        m = re.search(r"(?<!\\)%", line)
        if m:
            if re.search(r"%+\s*typed:", line[m.start():]):
                typed.add(i)
            line = line[: m.start()]
        out.append(line)
    return "\n".join(out), typed


def skip_group(text: str, i: int, open_c: str, close_c: str) -> int:
    """Index just past the balanced group starting at text[i] == open_c."""
    depth = 0
    for j in range(i, len(text)):
        if text[j] == "\\":
            continue
        if text[j] == open_c and (j == 0 or text[j - 1] != "\\"):
            depth += 1
        elif text[j] == close_c and text[j - 1] != "\\":
            depth -= 1
            if depth == 0:
                return j + 1
    return len(text)


def blank(text: str, a: int, b: int) -> str:
    """Replace text[a:b] with spaces, keeping newlines so line numbers hold."""
    return text[:a] + re.sub(r"[^\n]", " ", text[a:b]) + text[b:]


def drop_commands(text: str) -> str:
    pattern = re.compile(r"\\(" + "|".join(re.escape(c) for c in DROP) + r")\*?(?![A-Za-z])")
    pos = 0
    while True:
        m = pattern.search(text, pos)
        if not m:
            return text
        j = m.end()
        name = m.group(1)
        while True:  # optional and required arguments, with whitespace between
            k = j
            while k < len(text) and text[k] in " \t":
                k += 1
            if k < len(text) and text[k] == "[":
                j = skip_group(text, k, "[", "]")
            elif k < len(text) and text[k] == "{":
                j = skip_group(text, k, "{", "}")
            elif name in ("newcommand", "renewcommand", "providecommand", "def") and k < len(text) and text[k] == "\\":
                j = k + 1
                while j < len(text) and text[j].isalpha():
                    j += 1
            else:
                break
        text = blank(text, m.start(), j)
        pos = m.start() + 1


def math_spans(text: str) -> list[tuple[int, int]]:
    spans = []
    env = "|".join(re.escape(e) for e in MATH_ENVS)
    for m in re.finditer(r"\\begin\{(" + env + r")\}(.*?)\\end\{\1\}", text, re.S):
        spans.append((m.start(2), m.end(2)))
    for m in re.finditer(r"\\\[(.*?)\\\]|\\\((.*?)\\\)", text, re.S):
        spans.append((m.start(), m.end()))
    for m in re.finditer(r"(?<!\\)\$(.+?)(?<!\\)\$", text, re.S):
        spans.append((m.start(), m.end()))
    return sorted(spans)


def check_file(path: pathlib.Path, allow: list[re.Pattern], body_only: bool) -> list[tuple[int, str]]:
    raw = path.read_text()
    text, typed = strip_comments(raw)
    if body_only:
        k = text.find("\\begin{document}")
        text = blank(text, 0, k) if k >= 0 else text
    # The math environments' names are dropped with \begin/\end, so find math first, on the original layout.
    spans = math_spans(text)
    text = drop_commands(text)
    for rx in allow:
        for m in reversed(list(rx.finditer(text))):
            text = blank(text, m.start(), m.end())
    lines = raw.split("\n")
    found = []

    def in_math(pos: int) -> bool:
        return any(a <= pos < b for a, b in spans)

    for m in re.finditer(r"\d+(?:[.,]\d+)*", text):
        token = m.group()
        if in_math(m.start()) and not ("." in token or len(token.replace(",", "")) >= 2):
            continue
        line = text.count("\n", 0, m.start()) + 1
        if line in typed:
            continue
        found.append((line, lines[line - 1].strip()[:110]))
    return found


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("main", type=pathlib.Path)
    ap.add_argument("--allow", type=pathlib.Path, help="regular expressions for names that contain digits")
    ap.add_argument("--generated", default="generated", help="folder of generated files, relative to MAIN")
    ap.add_argument("--skip", nargs="*", default=["authors", "ai_usage"], help="\\input names not to check")
    a = ap.parse_args()
    root = a.main.parent
    allow = []
    if a.allow and a.allow.exists():
        allow = [re.compile(l.strip()) for l in a.allow.read_text().splitlines() if l.strip() and not l.startswith("#")]
    problems = []
    gen = (root / a.generated).resolve()
    for g in sorted(gen.glob("*.tex")):
        if not g.read_text().startswith(STAMP):
            problems.append(f"{g.relative_to(root)}:1: generated file without its stamp line ({STAMP} ...)")
    seen, todo = set(), [(a.main, True)]
    while todo:
        path, body_only = todo.pop()
        if path in seen or not path.exists():
            continue
        seen.add(path)
        text, _ = strip_comments(path.read_text())
        for name in re.findall(r"\\input\{([^}]+)\}", text):
            child = (root / name).with_suffix(".tex") if not name.endswith(".tex") else root / name
            if gen in child.resolve().parents or pathlib.Path(name).stem in a.skip:
                continue
            todo.append((child, False))
        for line, snippet in check_file(path, allow, body_only):
            problems.append(f"{path.relative_to(root) if root in path.parents or path.parent == root else path}:{line}: "
                            f"typed number: {snippet}")
    for p in problems:
        print(p)
    print(f"{len(problems)} finding(s)", file=sys.stderr)
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
